import pyomo.environ as pyo

# ---------------------------------------------------------------------------
# All numeric values taken from the problem statement.
# ---------------------------------------------------------------------------
DATA = {
    # identifiers of the three orders
    "orders": [1, 2, 3],
    # order width (m)
    "w": {1: 0.5, 2: 0.7, 3: 0.9},
    # order required length (m of that strip)
    "L": {1: 1000.0, 2: 3000.0, 3: 2000.0},
    # stock (parent) roll widths available (m)
    "stock_widths": [1.0, 2.0],
    # patterns are generated below from the order widths
    "patterns": None,
}


def _generate_patterns():
    """Enumerate every combination of strips of orders 1,2,3 that fits
    at most the widest stock roll (2 m)."""
    w1, w2, w3 = DATA["w"][1], DATA["w"][2], DATA["w"][3]
    widest = max(DATA["stock_widths"])
    patterns = []
    for n1 in range(int(widest // w1) + 1):
        for n2 in range(int(widest // w2) + 1):
            for n3 in range(int(widest // w3) + 1):
                used = n1 * w1 + n2 * w2 + n3 * w3
                if 1e-9 < used <= widest + 1e-9:
                    patterns.append({"n1": n1, "n2": n2, "n3": n3, "used": used})
    return patterns


DATA["patterns"] = _generate_patterns()


def build_model(data=None):
    d = data or DATA

    m = pyo.ConcreteModel()

    # ---- Sets -------------------------------------------------------------
    m.K = pyo.Set(initialize=list(range(len(d["stock_widths"]))), ordered=True)
    m.P = pyo.Set(initialize=list(range(len(d["patterns"]))), ordered=True)
    m.I = pyo.Set(initialize=list(d["orders"]), ordered=True)

    # plain python lookups (not model components)
    supp = {k: d["stock_widths"][k] for k in range(len(d["stock_widths"]))}
    pat = {p: d["patterns"][p] for p in range(len(d["patterns"]))}

    W_ONE_IDX = list(d["stock_widths"]).index(1.0)
    W_TWO_IDX = list(d["stock_widths"]).index(2.0)

    # ---- Allowed (stock, pattern) pairs -----------------------------------
    one_allowed = {
        p for p in range(len(d["patterns"]))
        if pat[p]["used"] <= supp[W_ONE_IDX] + 1e-9
    }
    two_allowed = {
        p for p in range(len(d["patterns"]))
        if pat[p]["used"] <= supp[W_TWO_IDX] + 1e-9
    }
    allowed = sorted(
        {(W_ONE_IDX, p) for p in one_allowed}
        | {(W_TWO_IDX, p) for p in two_allowed}
    )
    m.KP = pyo.Set(initialize=allowed, dimen=2, ordered=True)

    # ---- Variables --------------------------------------------------------
    m.x = pyo.Var(m.KP, within=pyo.NonNegativeReals, bounds=(0, None))

    # ---- Objective: minimise area of stock roll consumed ------------------
    def obj_rule(mo):
        return sum(mo.x[k, p] * supp[k] for (k, p) in mo.KP)

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # ---- Demand constraints ----------------------------------------------
    def rule_demand(mo, i):
        produced = 0
        for (k, p) in mo.KP:
            if i == 1:
                face = pat[p]["n1"]
            elif i == 2:
                face = pat[p]["n2"]
            else:
                face = pat[p]["n3"]
            produced += face * mo.x[k, p]
        return produced >= d["L"][i]

    m.demand = pyo.Constraint(m.I, rule=rule_demand)

    return m


