import pyomo.environ as pyo

DATA = {
    "orders": [1, 2, 3],
    "width": {1: 0.5, 2: 0.7, 3: 0.9},
    "length": {1: 1000, 2: 3000, 3: 2000},
    "stock_widths": [1, 2],
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    orders = d["orders"]
    stocks = d["stock_widths"]
    width = d["width"]
    length = d["length"]

    # Feasible patterns: max pieces of order i per stock roll of width s
    max_pieces = {}
    for i in orders:
        for s in stocks:
            max_pieces[(i, s)] = int(s // width[i])

    # Build pattern index sets (k = number of pieces per roll, 0..max_pieces)
    patterns = {}
    for i in orders:
        for s in stocks:
            patterns[(i, s)] = list(range(max_pieces[(i, s)] + 1))

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=orders)
    model.S = pyo.Set(initialize=stocks)

    # Rolls of stock width s allocated to order i
    model.cut = pyo.Var(model.I, model.S, within=pyo.NonNegativeIntegers)

    # use[i,s,k]: rolls of width s used for order i with k pieces per roll
    model.use = pyo.Var(
        [(i, s, k) for i in orders for s in stocks for k in patterns[(i, s)]],
        within=pyo.NonNegativeIntegers,
    )

    # Objective: minimize total stock area consumed
    def obj_rule(m):
        return sum(
            m.cut[i, s] * s * length[i]
            for i in m.I
            for s in m.S
        )
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Demand: total length produced for order i equals required length
    def demand_rule(m, i):
        return sum(
            m.use[i, s, k] * k * length[i]
            for s in stocks
            for k in patterns[(i, s)]
        ) == length[i]
    model.demand = pyo.Constraint(model.I, rule=demand_rule)

    # Link cut[i,s] to the pattern usage variables
    def link_rule(m, i, s):
        return m.cut[i, s] == sum(
            m.use[i, s, k] for k in patterns[(i, s)]
        )
    model.link = pyo.Constraint(model.I, model.S, rule=link_rule)

    return model
